/* The tables of M16 · Learning (LMS). */

/** Shared across branches unless limited to sections. */
export const learningResources = defineTable(
  'learning_resources',
  { module: 'M16', scope: 'org', member: { read: { status: 'published', audience: 'students' } } },
  {
    ...baseColumns,
    gradeSubjectId: uuid()
      .references((): AnyPgColumn => gradeSubjects.id)
      .notNull(),
    unitId: uuid().references((): AnyPgColumn => syllabusUnits.id),
    title: text().notNull(),
    description: text(),
    kind: enumText(learningResourceKinds).notNull(),
    /** required for `link` and `video`; `https` only */
    url: text(),
    /** required for `note`; rich text */
    body: text(),
    /** required for `file` */
    fileId: uuid().references((): AnyPgColumn => files.id),
    audience: enumText(learningResourceAudiences).notNull().default('students'),
    /** empty means every section of the grade */
    sectionIds: uuid()
      .array()
      .notNull()
      .default(sql`'{}'`),
    createdByStaffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    status: enumText(learningResourceStatuses).notNull().default('draft'),
    publishedAt: timestamptz(),
  },
  (t) => [
    check(
      'learning_resources_url_needed',
      sql`${t.kind} not in ('link', 'video') or ${t.url} is not null`,
    ),
    check('learning_resources_url_https', sql`${t.url} like 'https://%'`),
    check('learning_resources_body_needed', sql`${t.kind} <> 'note' or ${t.body} is not null`),
    check('learning_resources_file_id_needed', sql`${t.kind} <> 'file' or ${t.fileId} is not null`),
    index('learning_resources_grade_subject_unit_status_idx').on(
      t.orgId,
      t.gradeSubjectId,
      t.unitId,
      t.status,
    ),
  ],
);

export const resourceViews = defineTable(
  'resource_views',
  {
    module: 'M16',
    scope: 'org',
    family: 'studentId',
    appendOnly: true,
    staff: 'append',
    familyRule: 'append',
  },
  {
    ...appendColumns,
    resourceId: uuid()
      .references((): AnyPgColumn => learningResources.id)
      .notNull(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    viewedAt: timestamptz().notNull(),
  },
  (t) => [
    index('resource_views_resource_idx').on(t.orgId, t.resourceId),
    index('resource_views_student_viewed_at_idx').on(t.orgId, t.studentId, t.viewedAt),
  ],
);

export const quizzes = defineTable(
  'quizzes',
  { module: 'M16', scope: 'branch', member: { read: { status: ['published', 'closed'] } } },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    gradeSubjectId: uuid()
      .references((): AnyPgColumn => gradeSubjects.id)
      .notNull(),
    /** at least one */
    sectionIds: uuid().array().notNull(),
    createdByStaffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    title: text().notNull(),
    instructions: text(),
    unitId: uuid().references((): AnyPgColumn => syllabusUnits.id),
    opensAt: timestamptz().notNull(),
    closesAt: timestamptz().notNull(),
    /** empty means untimed within the window */
    durationMinutes: integer(),
    attemptsAllowed: integer().notNull().default(1),
    shuffleQuestions: boolean().notNull().default(true),
    shuffleOptions: boolean().notNull().default(true),
    showAnswers: enumText(quizShowAnswerses).notNull().default('after_close'),
    passPercent: decimal(5, 2).notNull().default(40),
    status: enumText(quizStatuses).notNull().default('draft'),
  },
  (t) => [
    check('quizzes_section_ids_some', sql`cardinality(${t.sectionIds}) >= 1`),
    check('quizzes_closes_at_after', sql`${t.closesAt} > ${t.opensAt}`),
    positive('quizzes', t.durationMinutes),
    between('quizzes', t.attemptsAllowed, 1, 5),
    between('quizzes', t.passPercent, 0, 100),
  ],
);

/** A frozen copy, so later edits to the bank never change a quiz already taken. */
export const quizQuestions = defineTable(
  'quiz_questions',
  { module: 'M16', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    quizId: uuid()
      .references((): AnyPgColumn => quizzes.id)
      .notNull(),
    /** the bank question it came from */
    questionId: uuid().references((): AnyPgColumn => questions.id),
    sortOrder: integer().notNull(),
    type: enumText(quizQuestionTypes).notNull(),
    text: text().notNull(),
    textUr: text(),
    /** `{ key, text }` */
    options: jsonb().notNull().default([]),
    /** never sent to students before answers are shown */
    correct: jsonb().notNull(),
    marks: decimal(5, 2).notNull(),
  },
  (t) => [positive('quiz_questions', t.marks)],
);

export const quizAttempts = defineTable(
  'quiz_attempts',
  {
    module: 'M16',
    scope: 'branch',
    family: 'studentId',
    familyRule: {
      read: true,
      insert: { status: 'in_progress' },
      update: { status: 'in_progress' },
    },
  },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    quizId: uuid()
      .references((): AnyPgColumn => quizzes.id)
      .notNull(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    /** 1, 2… */
    attemptNo: integer().notNull(),
    startedAt: timestamptz().notNull(),
    /** set by the server at start */
    deadlineAt: timestamptz().notNull(),
    submittedAt: timestamptz(),
    status: enumText(quizAttemptStatuses).notNull().default('in_progress'),
    /** this attempt's shuffled order */
    questionOrder: uuid().array().notNull(),
    score: decimal(6, 2),
    maxScore: decimal(6, 2).notNull(),
  },
  (t) => [
    positive('quiz_attempts', t.attemptNo),
    uniqueIndex('quiz_attempts_quiz_student_attempt_no_uq')
      .on(t.quizId, t.studentId, t.attemptNo)
      .where(live(t)),
  ],
);

export const quizAnswers = defineTable(
  'quiz_answers',
  {
    module: 'M16',
    scope: 'branch',
    family: 'studentId',
    familyRule: { read: true, insert: true, update: true },
  },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    attemptId: uuid()
      .references((): AnyPgColumn => quizAttempts.id)
      .notNull(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    quizQuestionId: uuid()
      .references((): AnyPgColumn => quizQuestions.id)
      .notNull(),
    answer: jsonb(),
    /** empty until graded */
    isCorrect: boolean(),
    marksAwarded: decimal(5, 2),
    /** short answers */
    gradedBy: uuid().references((): AnyPgColumn => profiles.id),
  },
  (t) => [
    uniqueIndex('quiz_answers_attempt_quiz_question_uq')
      .on(t.attemptId, t.quizQuestionId)
      .where(live(t)),
  ],
);

export const liveClasses = defineTable(
  'live_classes',
  { module: 'M16', scope: 'branch', member: 'read' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    sectionSubjectId: uuid()
      .references((): AnyPgColumn => sectionSubjects.id)
      .notNull(),
    title: text().notNull(),
    startsAt: timestamptz().notNull(),
    endsAt: timestamptz().notNull(),
    platform: enumText(liveClassPlatforms).notNull(),
    /** `https` only */
    joinUrl: text().notNull(),
    recordingUrl: text(),
    status: enumText(liveClassStatuses).notNull().default('scheduled'),
  },
  (t) => [
    check('live_classes_ends_at_after', sql`${t.endsAt} > ${t.startsAt}`),
    check('live_classes_join_url_https', sql`${t.joinUrl} like 'https://%'`),
  ],
);
